import unittest

from refunds import refund_cents


class RefundTests(unittest.TestCase):
    def test_sums_payment_record_formats(self):
        records = [
            {'amount_minor': 123, 'amount': '9.99'},
            {'amount': '1.005'},
            {'amount': '-0.505'},
        ]
        self.assertEqual(refund_cents(records), 173)

    def test_empty_records(self):
        self.assertEqual(refund_cents([]), 0)
